const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.bag}</svg>`;
const money=(v,sign=false)=>(sign&&v>0?'+':'')+'¥'+Math.abs(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const num=v=>v.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const sources={wx:{name:'微信支付',mark:'微'},ali:{name:'支付宝',mark:'支'},cmb:{name:'招商银行',mark:'招'}};
const cats={'居住生活':{color:'#6e8461',icon:'home'},'餐饮美食':{color:'#e99a72',icon:'coffee'},'购物消费':{color:'#d6bb88',icon:'bag'},'交通出行':{color:'#a6b59c',icon:'car'},'休闲娱乐':{color:'#a5b3bc',icon:'spark'},'其他支出':{color:'#d8ded2',icon:'tag'},'待分类':{color:'#e6d6c0',icon:'tag'}};
const base=[
['09-01','房屋租金',4200,'居住生活','cmb'],['09-01','盒马鲜生',236.5,'居住生活','ali,cmb'],['09-02','瑞幸咖啡',18,'餐饮美食','wx,cmb'],['09-03','滴滴出行',42.8,'交通出行','wx,cmb'],['09-03','MUJI 无印良品',329,'购物消费','ali'],['09-04','地铁乘车码',8,'交通出行','ali,cmb'],['09-05','阿姨的家常菜',88,'餐饮美食','wx'],['09-06','山间面包房',54,'餐饮美食','wx'],['09-06','优衣库',699,'购物消费','ali,cmb'],['09-07','国家电网',186.7,'居住生活','ali'],['09-08','腾讯视频',30,'休闲娱乐','wx'],['09-09','小象超市',167.8,'居住生活','wx,cmb'],['09-10','西贝莜面村',218,'餐饮美食','ali'],['09-11','滴滴出行',56.4,'交通出行','ali'],['09-12','京东自营',899,'购物消费','wx,cmb'],['09-13','周末小馆',128,'餐饮美食','wx'],['09-14','中国移动',99,'居住生活','ali'],['09-15','美团外卖',36,'餐饮美食','wx'],['09-16','城市书店',146,'休闲娱乐','ali'],['09-17','晨光生活店',86,'待分类','wx'],['09-18','叮咚买菜',192.3,'居住生活','ali,cmb'],['09-19','连锁咖啡店',32,'餐饮美食','wx'],['09-20','电影院',116,'休闲娱乐','ali'],['09-21','铁路出行',553,'交通出行','ali,cmb'],['09-22','城市运动馆',280,'休闲娱乐','wx'],['09-23','苏小柳',168,'餐饮美食','wx'],['09-24','山姆会员商店',648,'居住生活','wx,cmb'],['09-25','京东自营 · 已匹配退款',-99,'购物消费','wx,cmb'],['09-26','美团外卖',43.8,'餐饮美食','wx']];
const prev=[['08-01','房屋租金',4200,'居住生活','cmb'],['08-04','八月餐饮样例',1450,'餐饮美食','wx'],['08-06','八月购物样例',1599,'购物消费','ali,cmb'],['08-08','八月交通样例',480,'交通出行','ali'],['08-12','八月超市样例',930,'居住生活','wx,cmb'],['08-16','八月休闲样例',450,'休闲娱乐','ali'],['08-20','八月生活缴费',310,'居住生活','cmb'],['08-25','八月餐饮样例',390,'餐饮美食','wx'],['08-26','八月其他样例',180,'其他支出','ali'],['08-29','八月月末样例',300,'购物消费','wx']];
function mk(rows,prefix){return rows.map((r,i)=>({id:prefix+i,date:'2026-'+r[0],merchant:r[1],amount:r[2],cat:r[3],sources:r[4].split(','),type:r[2]<0?'refund':'expense',note:'虚构样例交易，仅用于演示',raw:r[4].split(',').map((s,j)=>({source:s,ref:`DEMO-${prefix.toUpperCase()}${String(i+1).padStart(3,'0')}-${j+1}`,amount:r[2]}))}));}
let transactions=[],reviews={},imports=[],page='report',month='09',filters={q:'',cat:'all',source:'all',type:'all'};
function reset(){transactions=[...mk(base,'s'),...mk(prev,'a'),{id:'transfer',date:'2026-09-10',merchant:'本人账户互转',amount:3000,cat:'账户划转',sources:['cmb','ali'],type:'transfer',raw:[{source:'cmb',ref:'DEMO-TRANSFER-01',amount:3000},{source:'ali',ref:'DEMO-TRANSFER-02',amount:-3000}]},{id:'repay',date:'2026-09-18',merchant:'招商银行信用卡还款',amount:2800,cat:'信用卡还款',sources:['cmb'],type:'repayment',raw:[{source:'cmb',ref:'DEMO-REPAY-01',amount:2800}]}];reviews={duplicate:false,refund:false,category:false};imports=[];page='report';month='09';filters={q:'',cat:'all',source:'all',type:'all'};render();}
const sourceTag=s=>`<span class="source-tag"><span class="source-logo ${s}">${sources[s].mark}</span>${sources[s].name}</span>`;
const countReview=()=>Object.values(reviews).filter(x=>!x).length;
const inMonth=t=>t.date.slice(5,7)===month;
const spending=t=>t.type==='expense'||t.type==='refund';
const current=()=>transactions.filter(inMonth);
const spent=ts=>Math.round(ts.filter(spending).reduce((s,t)=>s+t.amount,0)*100)/100;
const categoryTotals=ts=>Object.keys(cats).map(c=>({name:c,total:Math.round(ts.filter(t=>spending(t)&&t.cat===c).reduce((s,t)=>s+t.amount,0)*100)/100,...cats[c]})).filter(c=>c.total>0).sort((a,b)=>b.total-a.total);
function monthInfo(){let ts=current(),net=spent(ts),refund=-ts.filter(t=>t.type==='refund').reduce((s,t)=>s+t.amount,0),excluded=ts.filter(t=>!spending(t)).reduce((s,t)=>s+Math.abs(t.amount),0);return{ts,net,refund,excluded,gross:net+refund,raw:ts.reduce((n,t)=>n+t.raw.length,0),linked:ts.filter(t=>t.raw.length>1).length,count:ts.filter(t=>t.type==='expense').length};}
const titles={report:['消费报告','钱花在哪里，一眼就明白。'],import:['账单导入','一次导入，归集一整段生活。'],review:['待确认','把不确定的几笔，交给你来决定。'],ledger:['交易明细','每一笔支出，都有来处。']};
function render(){const nav=[['report','grid','消费报告'],['import','upload','账单导入'],['review','check','待确认'],['ledger','list','交易明细']];document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">${icon('repeat')}</span>moneygo<span class="dot">.</span></div><div class="workspace">MY MONEY, MY WAY</div><nav class="nav" aria-label="主导航">${nav.map(([id,i,t])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}${t}${id==='review'&&countReview()?`<span class="count">${countReview()}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="side-note">${icon('shield')}只属于你的账本<br>少一点记账，多一点生活。</div><div class="person"><div class="avatar">M</div><div>我的个人账本<small>交互原型 · 虚构数据</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">个人账本 ${icon('chevron')} <span>${titles[page][0]}</span></div><div class="brand mobile-brand"><span class="brandmark">${icon('repeat')}</span>moneygo<span class="dot">.</span></div><div class="top-right"><a class="btn" href="index.html">返回我的账本</a><span class="demo-label">DEMO · 虚构示例</span><button class="iconbutton" data-action="method" aria-label="查看统计口径">${icon('info')}</button><div class="avatar" aria-hidden="true">M</div></div></header><section class="heading"><div><div class="eyebrow">A LITTLE CLARITY, EVERY MONTH</div><h1>${titles[page][1]}</h1><p class="subtitle">${page==='report'?'不用一笔笔记账。从账单里，重新认识你的消费习惯。':page==='import'?'支持流程演示：微信支付、支付宝、招商银行。':page==='review'?'规则只给建议。确认后，消费报告会同步更新。':'归集后的交易与原始来源，可随时核对。'}</p></div><div class="actions">${page==='report'||page==='ledger'?`<select class="month-select" id="month" aria-label="选择报告月份"><option value="09" ${month==='09'?'selected':''}>2026 年 9 月</option><option value="08" ${month==='08'?'selected':''}>2026 年 8 月</option></select>`:''}${page==='report'||page==='ledger'?`<button class="btn primary" data-page="import">${icon('plus')}导入账单</button>`:page==='review'?`<span class="tiny-label">${countReview()} 笔待确认</span>`:`<button class="btn ghost" data-action="method">${icon('info')}处理规则</button>`}</div></section>${page==='report'?report():page==='import'?importPage():page==='review'?reviewPage():ledger()}<footer class="page-foot"><span>所有商户、交易与金额均为虚构样例 · 修改仅本次页面有效，刷新即重置</span><button data-action="reset">重置演示</button></footer></main></div>`;bind();}
function report(){let m=monthInfo(),ct=categoryTotals(m.ts),p=transactions.filter(t=>t.date.slice(5,7)==='08'&&Number(t.date.slice(8))<=26),comparison=(spent(transactions.filter(t=>t.date.slice(5,7)==='09'&&Number(t.date.slice(8))<=26))/spent(p)-1)*100;const colors=ct.map((c,i)=>{let start=ct.slice(0,i).reduce((s,c)=>s+c.total,0)/m.net*100,end=start+c.total/m.net*100;return `${c.color} ${start}% ${end}%`}).join(',');const top=ct[0];let recent=m.ts.filter(spending).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);return `<section class="stats"><article class="stat hero"><div class="stat-label">本月净消费 <button class="iconbutton" data-action="method" aria-label="净消费计算方式">${icon('info')}</button></div><div class="big-number"><span class="currency">¥</span>${num(m.net)}</div><div class="stat-foot">${month==='09'?`<span class="trend ${comparison<0?'good':''}">${comparison<0?'↘':'↗'} ${Math.abs(comparison).toFixed(1)}%</span>较 8 月同期（1—26 日）`:'<span>8 月完整月份样例 · 不代表真实消费</span>'}</div></article><article class="stat"><div class="stat-label">已归集消费</div><div class="big-number secondary">${m.count}<span style="font-size:13px;color:#939c87;margin-left:7px;letter-spacing:0">笔</span></div><div class="stat-foot">${m.linked} 组多来源记录已关联</div></article><article class="stat"><div class="stat-label">已抵扣退款</div><div class="big-number secondary"><span class="currency">¥</span>${num(m.refund)}</div><div class="stat-foot">按退款到账月份抵扣消费</div></article></section><div class="source-strip"><div class="source-group"><span>数据来源</span>${sourceTag('wx')}${sourceTag('ali')}${sourceTag('cmb')}<span class="sep">|</span><button class="text-link" data-page="import">查看导入记录 ${icon('arrow')}</button></div><span class="muted">${month==='09'?(imports.length?'部分来源已补入月底样例':'已覆盖 09.01—09.26'):'已覆盖 08.01—08.31'}</span></div><section class="content-grid"><article class="card"><div class="card-head"><div><h2>钱都花在哪儿</h2><p>按分类，找到消费的重心</p></div><span class="tiny-label">净消费口径</span></div><div class="category-area"><div class="donut" style="background:conic-gradient(${colors})" role="img" aria-label="消费分类占比图"><div class="donut-center"><span>最大支出</span><strong>${(top.total/m.net*100).toFixed(0)}<span style="font-size:14px">%</span></strong><span>${top.name}</span></div></div><div class="legend">${ct.map(c=>`<button class="legend-row" data-category="${c.name}" aria-label="查看${c.name}交易"><span class="legend-name"><i class="swatch" style="background:${c.color}"></i>${c.name}</span><span class="legend-value"><span>¥${Math.round(c.total).toLocaleString()}</span><span>${(c.total/m.net*100).toFixed(0)}%</span></span></button>`).join('')}</div></div><div class="insight">${icon('spark')}<span><strong>${top.name}占本月消费 ${(top.total/m.net*100).toFixed(1)}%。</strong><br>${top.name==='居住生活'?'其中房租 ¥4,200.00，是最大的单笔支出。':'点击分类即可查看对应交易。'} <button class="text-link" data-tx="${month==='09'?'s0':'a0'}">查看依据 ${icon('arrow')}</button></span></div></article><article class="card trend-card"><div class="card-head"><div><h2>消费节奏</h2><p>每周花费，让变化更清楚</p></div><div class="chart-legend"><span><i style="background:#e9ede3"></i>8月</span><span><i style="background:#eb966f"></i>9月</span></div></div>${chart()}<div class="chart-footer"><span>第 4 段为 22 日至月末</span><strong>点击柱状图查看区间金额</strong></div></article></section><section class="bottom-grid"><article class="card"><div class="card-head"><h2>最近的几笔</h2><button class="text-link" data-page="ledger">全部交易 ${icon('arrow')}</button></div><div class="transaction-list">${recent.map(txRow).join('')}</div></article><article class="card"><div class="card-head"><h2>还差你确认一下</h2><span class="tiny-label">${countReview()} 笔</span></div>${countReview()?`${!reviews.duplicate?mini('repeat','可能是同一笔消费','周末小馆 · 微信与银行卡记录','duplicate'):''}${!reviews.refund?mini('refund','一笔退款待匹配','MUJI 无印良品 · ¥129.00','refund'):''}${!reviews.category?mini('tag','这笔该放在哪一类？','晨光生活店 · ¥86.00','category'):''}`:`<div class="empty" style="padding:25px 0">${icon('check')}<p>都确认好了，账本更清楚了。</p></div>`}<div class="history-note">待确认的重复项与退款暂不计入。<br>待分类消费已计入总额。</div></article></section>`;}
function chart(){let vals=['08','09'].map(m=>[0,1,2,3].map(w=>spent(transactions.filter(t=>t.date.slice(5,7)===m&&Math.min(3,Math.floor((Number(t.date.slice(8))-1)/7))===w))));let max=Math.ceil(Math.max(...vals.flat())/2000)*2000;return `<div class="bar-chart"><div class="gridlines">${[max,max/2,0].map(x=>`<div class="gridline"><span>${x?x/1000+'k':'0'}</span></div>`).join('')}</div><div class="bars">${[0,1,2,3].map(w=>`<div class="bar-group"><button class="bar previous" style="height:${vals[0][w]/max*150}px;border:0" data-bar="8月 ${w*7+1}—${w===3?31:w*7+7}日：${money(vals[0][w])}" aria-label="8月第${w+1}段 ${money(vals[0][w])}"></button><button class="bar current" style="height:${vals[1][w]/max*150}px;border:0" data-bar="9月 ${w*7+1}—${w===3?30:w*7+7}日：${money(vals[1][w])}（已导入样例）" aria-label="9月第${w+1}段 ${money(vals[1][w])}"></button><label>第 ${w+1} 段</label></div>`).join('')}</div></div>`;}
const mini=(i,t,d,id)=>`<div class="review-mini"><div class="review-badge">${icon(i)}</div><div><p>${t}</p><small>${d}</small></div><button class="text-link" data-review="${id}">确认 ${icon('chevron')}</button></div>`;
function txRow(t){return `<button class="transaction-row" data-tx="${t.id}"><span class="merchant-icon">${icon(cats[t.cat]?.icon||'repeat')}</span><span><div class="tx-name">${t.merchant}</div><div class="tx-meta">${t.date.slice(5).replace('-','月')}日 · ${t.cat}</div></span><span class="tx-amount ${t.amount<0?'refund-amount':''}">${t.amount<0?'+':'−'}${money(t.amount)}<small>${t.sources.length>1?'多来源已关联':sources[t.sources[0]].name}</small></span></button>`;}
function importPage(){return `<div class="notice">${icon('shield')}<span>这是可点击的流程原型，所有数据均为虚构。你可以载入内置样例体验归集；当前不读取、上传或解析真实账单，也未连接银行或支付账户。</span></div><div class="source-cards">${Object.keys(sources).map(s=>`<article class="card source-card"><span class="source-logo ${s}">${sources[s].mark}</span><h3>${sources[s].name}</h3><p>${s==='wx'?'支付账单导出文件':s==='ali'?'收支明细导出文件':'借记卡 / 信用卡交易明细'}<br>真实格式适配仍待实现与验证</p><div class="coverage"><span>9 月样例覆盖</span><span>01—${imports.includes(s)?'30':'26'} 日</span></div><button class="btn ${imports.includes(s)?'soft':''}" data-import="${s}" ${imports.includes(s)?'disabled':''}>${icon(imports.includes(s)?'check':'plus')}${imports.includes(s)?'月底样例已导入':'载入月底样例'}</button></article>`).join('')}</div><div class="import-dash"><div><h3>月末，给账本补个全。</h3><p>导入之后，先关联重复记录，再核对退款与分类。<br>已有样例不会重复计入，跨来源付款只算一笔消费。</p></div><button class="btn dark" data-page="review">核对 ${countReview()} 笔待确认 ${icon('arrow')}</button></div><article class="card table-card"><div class="card-head"><h2>导入记录</h2><span class="tiny-label">仅内置示例批次</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>账单来源</th><th>日期覆盖</th><th>原始记录</th><th>处理状态</th></tr></thead><tbody>${imports.map(s=>`<tr><td>${sourceTag(s)}<div class="muted" style="margin-top:6px">DEMO_${s}_月底样例</div></td><td>09.27—09.30</td><td>${s==='cmb'?2:1} 条</td><td><span class="tag">已归集 · 样例</span></td></tr>`).join('')}${Object.keys(sources).map(s=>`<tr><td>${sourceTag(s)}<div class="muted" style="margin-top:6px">DEMO_${s}_基础样例</div></td><td>09.01—09.26</td><td>${mk(base,'s').reduce((n,t)=>n+t.raw.filter(r=>r.source===s).length,0)+(s==='cmb'?3:s==='ali'?2:0)} 条</td><td><span class="tag">已归集 · 样例</span></td></tr>`).join('')}</tbody></table></div><p class="history-note">待确认队列另含招商银行重复候选 1 条、支付宝退款候选 1 条。每个批次只允许载入一次。</p></article>`;}
function reviewPage(){if(!countReview())return `<article class="card"><div class="empty">${icon('check')}<h3>这一次，都理清楚了。</h3><p>3 项确认已反映在消费报告与交易明细中。<br>刷新页面或重置演示可重新体验。</p><button class="btn primary" style="margin-top:22px" data-page="report">看看消费报告 ${icon('arrow')}</button></div></article>`;return `<div class="notice">${icon('info')}<span>确认前：重复候选与未匹配退款不计入净消费；待分类消费计入「待分类」。这里展示的是预设规则建议，不是真实 AI 分析。</span></div>${!reviews.duplicate?`<article class="card review-card" id="review-duplicate"><div class="review-title"><div class="review-badge">${icon('repeat')}</div><div><h3>这两条，是同一笔付款吗？</h3><p>金额一致，时间相差 2 秒，付款渠道指向同一银行卡。建议关联。</p></div><span class="tag orange">可能重复</span></div><div class="comparison"><div class="compare-item">${sourceTag('wx')}<strong>¥128.00</strong><small>周末小馆 · 09.13 18:42:06<br>当前已计入消费</small></div><div class="compare-item">${sourceTag('cmb')}<strong>¥128.00</strong><small>财付通快捷支付 · 09.13 18:42:08<br>候选记录暂未计入</small></div></div><div class="resolve-actions"><span>关联后保留两条来源，只计一次 ¥128。</span><button class="btn" data-resolve="separate">不是同一笔</button><button class="btn primary" data-resolve="duplicate">确认关联</button></div></article>`:''}${!reviews.refund?`<article class="card review-card" id="review-refund"><div class="review-title"><div class="review-badge">${icon('refund')}</div><div><h3>退款，找到了原来的那一笔。</h3><p>商户相同、示例订单引用一致，建议作为部分退款关联。</p></div><span class="tag orange">退款待匹配</span></div><div class="comparison"><div class="compare-item">原始消费<strong>¥329.00</strong><small>MUJI 无印良品 · 09.03<br>支付宝 · 购物消费</small></div><div class="compare-item">部分退款<strong>+¥129.00</strong><small>MUJI 无印良品 · 09.24<br>待确认，暂未抵扣</small></div></div><div class="resolve-actions"><span>确认后，9 月净消费减少 ¥129.00。</span><button class="btn primary" data-resolve="refund">确认退款匹配</button></div></article>`:''}${!reviews.category?`<article class="card review-card" id="review-category"><div class="review-title"><div class="review-badge">${icon('tag')}</div><div><h3>晨光生活店，算在哪一类？</h3><p>09.17 · 微信支付 · ¥86.00。商户名称不足以确定消费用途。</p></div><span class="tag orange">分类不确定</span></div><div class="resolve-actions"><span>已计入总额；修改分类不会改变净消费。</span><select class="category-select" id="review-cat" aria-label="选择消费分类">${Object.keys(cats).filter(c=>c!=='待分类').map(c=>`<option ${c==='购物消费'?'selected':''}>${c}</option>`).join('')}</select><button class="btn primary" data-resolve="category">确认分类</button></div></article>`:''}`;}
function filtered(){return current().filter(t=>(!filters.q||(t.merchant+' '+t.id+' '+t.raw.map(r=>r.ref).join(' ')).toLowerCase().includes(filters.q.toLowerCase()))&&(filters.cat==='all'||t.cat===filters.cat)&&(filters.source==='all'||t.sources.includes(filters.source))&&(filters.type==='all'||t.type===filters.type));}
function ledger(){let ts=filtered().sort((a,b)=>b.date.localeCompare(a.date));return `<article class="card table-card"><div class="card-head"><h2>归集交易</h2><button class="text-link" data-action="method">统计口径 ${icon('info')}</button></div><div class="filters"><label class="search">${icon('search')}<input id="search" placeholder="搜索商户、样例交易编号…" value="${filters.q.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;')}" aria-label="搜索交易"></label><select class="month-select" id="filter-cat" aria-label="筛选分类"><option value="all">全部分类</option>${[...Object.keys(cats),'账户划转','信用卡还款'].map(c=>`<option ${filters.cat===c?'selected':''}>${c}</option>`).join('')}</select><select class="month-select" id="filter-source" aria-label="筛选来源"><option value="all">全部来源</option>${Object.entries(sources).map(([s,v])=>`<option value="${s}" ${filters.source===s?'selected':''}>${v.name}</option>`).join('')}</select><select class="month-select" id="filter-type" aria-label="筛选类型"><option value="all">全部类型</option>${Object.entries({expense:'消费',refund:'退款',transfer:'账户划转',repayment:'信用卡还款'}).map(([k,v])=>`<option value="${k}" ${filters.type===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="ledger-summary"><span>当前筛选 <strong>${ts.length} 笔</strong></span><span>净消费 <strong>${money(spent(ts))}</strong></span><span>划转与还款不计入消费</span><button class="text-link" data-action="clear-filters">清除筛选</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>日期 / 商户</th><th>分类</th><th>归集金额</th><th>来源</th><th>处理状态</th></tr></thead><tbody>${ts.map(t=>`<tr data-tx="${t.id}" tabindex="0" role="button" aria-label="查看${t.merchant}交易详情"><td>${t.merchant}<div class="muted" style="margin-top:6px">${t.date}</div></td><td>${t.cat}</td><td style="color:${t.amount<0?'#4b8964':'#526048'}">${t.amount<0?'+':spending(t)?'−':''}${money(t.amount)}</td><td><div class="source-group">${t.sources.map(sourceTag).join('')}</div></td><td><span class="tag ${t.cat==='待分类'?'orange':''}">${!spending(t)?'不计消费':t.type==='refund'?'已匹配退款':t.cat==='待分类'?'待分类':t.sources.length>1?'多来源关联':'已归集'}</span></td></tr>`).join('')}</tbody></table>${ts.length?'':'<div class="empty">没有符合条件的样例交易。<br>试试清除筛选或更换关键词。</div>'}</div><p class="history-note">点击一行查看原始来源与计算依据。归集金额只显示一次，关联的支付平台记录与银行卡扣款不重复相加。</p></article>`;}
function bind(){document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{page=el.dataset.page;render();window.scrollTo({top:0,behavior:'smooth'});});document.querySelector('#month')?.addEventListener('change',e=>{month=e.target.value;render();});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{let a=el.dataset.action;if(a==='method')showMethod();if(a==='reset')modal('重置演示',`<p>将恢复全部虚构样例，清除本页的确认结果与模拟导入记录。</p>`,`<button class="btn" data-close>取消</button><button class="btn primary" id="confirm-reset">重置演示</button>`,()=>document.querySelector('#confirm-reset').onclick=()=>{reset();closeModal();toast('演示已重置');});if(a==='clear-filters'){filters={q:'',cat:'all',source:'all',type:'all'};render();}});document.querySelectorAll('[data-category]').forEach(el=>el.onclick=()=>{filters={q:'',cat:el.dataset.category,source:'all',type:'all'};page='ledger';render();});document.querySelectorAll('[data-tx]').forEach(el=>{el.onclick=()=>showTx(el.dataset.tx);el.onkeydown=e=>{if(e.key==='Enter')showTx(el.dataset.tx)}});document.querySelectorAll('[data-review]').forEach(el=>el.onclick=()=>{page='review';render();document.querySelector('#review-'+el.dataset.review)?.scrollIntoView({behavior:'smooth',block:'center'})});document.querySelectorAll('[data-resolve]').forEach(el=>el.onclick=()=>resolve(el.dataset.resolve));document.querySelectorAll('[data-import]').forEach(el=>el.onclick=()=>showImport(el.dataset.import));document.querySelectorAll('[data-bar]').forEach(el=>el.onclick=()=>toast(el.dataset.bar));document.querySelector('#search')?.addEventListener('input',e=>{let pos=e.target.selectionStart;filters.q=e.target.value;render();let n=document.querySelector('#search');n.focus();n.setSelectionRange(pos,pos)});['cat','source','type'].forEach(k=>document.querySelector('#filter-'+k)?.addEventListener('change',e=>{filters[k]=e.target.value;render()}));}
let lastFocus=null;
function modal(title,body,buttons='',onready){lastFocus=document.activeElement;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-head"><h2>${title}</h2><button data-close aria-label="关闭">${icon('close')}</button></div>${body}${buttons?`<div class="modal-bottom">${buttons}</div>`:''}</section></div>`;document.body.style.overflow='hidden';document.querySelectorAll('[data-close]').forEach(el=>el.onclick=closeModal);document.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};document.querySelector('.modal [data-close]')?.focus();onready?.();}
function closeModal(){document.querySelector('#modal-root').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();}
document.addEventListener('keydown',e=>{let m=document.querySelector('.modal');if(!m)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){let a=[...m.querySelectorAll('button:not(:disabled),input,select,[tabindex="0"]')];let f=a[0],l=a[a.length-1];if(e.shiftKey&&document.activeElement===f){e.preventDefault();l.focus()}else if(!e.shiftKey&&document.activeElement===l){e.preventDefault();f.focus()}}});
let toastTimer;function toast(t){let e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),4200);}
function showTx(id){let t=transactions.find(t=>t.id===id);if(!t)return;modal('交易详情',`<div class="detail-amount">${t.amount<0?'+':spending(t)?'−':''}${money(t.amount)}<small>${t.merchant}</small></div><div class="details"><div class="detail-row"><span>交易日期</span><span>${t.date}</span></div><div class="detail-row"><span>消费分类</span><span>${t.cat}</span></div><div class="detail-row"><span>统计处理</span><span>${!spending(t)?'账户资金移动，不计消费':t.type==='refund'?'已匹配退款，抵扣当月消费':t.raw.length>1?'多来源关联，仅计入一次':'计入当月净消费'}</span></div><div class="detail-row"><span>样例交易 ID</span><span>DEMO-${t.id.toUpperCase()}</span></div></div><p style="margin:17px 0 7px">原始来源 · ${t.raw.length} 条样例记录</p>${t.raw.map(r=>`<div class="raw-source"><strong>${sources[r.source].name} ${money(r.amount)}</strong><code>${r.ref}</code><br>${r.source==='cmb'&&spending(t)&&t.sources.length>1?'银行卡扣款 / 退款，与支付平台记录关联':'虚构原始记录，供交互演示'}</div>`).join('')}${t.id==='s4'&&reviews.refund?'<div class="notice" style="margin:15px 0 0;font-size:11px">已关联部分退款 ¥129.00，订单净消费 ¥200.00。</div>':''}${t.id==='s24'||t.id==='s26'?'':''}<p style="margin-top:15px">${t.type==='refund'?`原消费：${t.id==='refund-new'?'MUJI 无印良品 · DEMO-S4':'京东自营 · DEMO-S14'}。本原型按退款到账月份抵扣。`:'金额与来源均为合成数据，不代表真实账户。'}</p>`);}
function showMethod(){let m=monthInfo();modal('我们怎样算清这笔账',`<p>当前为 ${month==='09'?'9':'8'} 月已导入样例，所有金额可在交易明细中追溯。</p><div class="accounting-steps"><div class="accounting-step"><strong>1. 净消费 = 消费 − 已匹配退款</strong>${money(m.gross)} − ${money(m.refund)} = ${money(m.net)}。以交易发生月记消费，以退款到账月抵扣。</div><div class="accounting-step"><strong>2. 付款只算一次</strong>支付平台与银行卡记录关联后保留来源，只计一笔消费。待确认重复候选暂不计入。</div><div class="accounting-step"><strong>3. 自己的钱移动，不是消费</strong>账户互转与信用卡还款共 ${money(m.excluded)}，不计入净消费。信用卡还款不再次计费，实际购买由消费记录体现。</div><div class="accounting-step"><strong>4. 不确定的项目，明确标出</strong>未匹配退款暂不抵扣；待分类消费仍计入总额。确认后实时重算。</div><div class="accounting-step"><strong>5. 月份比较保持同口径</strong>9 月环比只比较 1—26 日；周图展示各月已载入记录，不将未覆盖日期当作零消费。分类占比按净额计算，图例金额按元四舍五入。</div></div><p style="margin-top:17px">当前原型没有真实文件解析、账户连接、AI 服务或生产级数据存储。所有修改仅保存在本页面内存中。</p>`);}
function resolve(type){if(type==='duplicate'&&!reviews.duplicate){let t=transactions.find(t=>t.id==='s15');t.sources.push('cmb');t.raw.push({source:'cmb',ref:'DEMO-DUPLICATE-01',amount:128});reviews.duplicate=true;toast('已关联两条来源，净消费不变');}if(type==='separate'&&!reviews.duplicate){modal('将候选作为另一笔消费？','<p>招商银行候选将独立计入餐饮消费。9 月净消费会增加 ¥128.00。你可以重置演示撤销。</p>','<button class="btn" data-close>返回核对</button><button class="btn primary" id="confirm-separate">确认计为另一笔</button>',()=>document.querySelector('#confirm-separate').onclick=()=>{transactions.push(...mk([['09-13','周末小馆 · 独立银行卡交易',128,'餐饮美食','cmb']],'separate'));reviews.duplicate=true;closeModal();render();toast('已计为独立消费，9 月净消费增加 ¥128.00')});return;}if(type==='refund'&&!reviews.refund){transactions.push({...mk([['09-24','MUJI 无印良品 · 部分退款',-129,'购物消费','ali']],'r')[0],id:'refund-new'});reviews.refund=true;toast('退款已匹配，9 月净消费减少 ¥129.00');}if(type==='category'&&!reviews.category){let c=document.querySelector('#review-cat').value;transactions.find(t=>t.id==='s19').cat=c;reviews.category=true;toast('分类已更新，净消费不变');}render();}
function showImport(s){if(imports.includes(s))return;const records=s==='wx'?[['09-28','月末咖啡',28,'餐饮美食','wx']]:s==='ali'?[['09-29','月末日用采购',168,'购物消费','ali']]:[['09-28','月末咖啡',28,'餐饮美食','cmb'],['09-29','月末日用采购',168,'购物消费','cmb']];modal(`载入${sources[s].name}样例`,`<p>无需选择或上传文件。这会载入 ${records.length} 条内置虚构记录，演示批量归集流程。</p><div class="file-preview"><strong>DEMO_${s}_20260927_20260930</strong>覆盖日期：2026.09.27—09.30<br>${records.map(r=>`${r[1]} · ${money(r[2])}`).join('<br>')}<div class="progress"><div id="import-progress"></div></div></div><p>同一笔月末消费在支付平台和银行卡中使用相同的样例关联 ID，多来源重复导入只补充来源，不增加消费金额。</p>`,`<button class="btn" data-close>取消</button><button class="btn primary" id="confirm-import">载入内置样例 ${icon('arrow')}</button>`,()=>{document.querySelector('#confirm-import').onclick=()=>{let b=document.querySelector('#confirm-import');b.disabled=true;b.textContent='正在归集样例…';document.querySelector('#import-progress').style.width='100%';setTimeout(()=>{let added=0,linked=0;records.forEach((r,i)=>{let id=r[1]==='月末咖啡'?'import-coffee':'import-shopping';let t=transactions.find(x=>x.id===id);if(t){if(!t.sources.includes(s)){t.sources.push(s);t.raw.push({source:s,ref:`DEMO-IMPORT-${s.toUpperCase()}-${i+1}`,amount:r[2]});linked++;}}else{t={...mk([r],'import')[0],id};t.raw=[{source:s,ref:`DEMO-IMPORT-${s.toUpperCase()}-${i+1}`,amount:r[2]}];transactions.push(t);added++;}});imports.push(s);closeModal();render();toast(`样例已导入：新增 ${added} 笔消费，关联 ${linked} 条已有来源`);},650);}});}
window.moneygoDebug={get transactions(){return transactions},get reviews(){return reviews},get imports(){return imports},spent,monthInfo,categoryTotals,reset};
reset();
